CREATE TYPE "Role" AS ENUM ('EARNER','BUSINESS','ADMIN');CREATE TYPE "CampaignStatus" AS ENUM ('DRAFT','LIVE','PAUSED','CLOSED');CREATE TYPE "CampaignType" AS ENUM ('ORDER','LEAD','CONTENT','REFERRAL');CREATE TYPE "OrderStatus" AS ENUM ('SUBMITTED','ACCEPTED','DELIVERED','CANCELLED');CREATE TYPE "RewardStatus" AS ENUM ('PENDING','EARNED','PAYABLE','PAID','REVERSED');CREATE TYPE "LedgerKind" AS ENUM ('REWARD_EARNED','PAYOUT','REWARD_REVERSAL');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"phone" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "EarnerProfile" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE,"displayName" TEXT NOT NULL,CONSTRAINT "EarnerProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id"));
CREATE TABLE "Business" ("id" TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"verified" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "Business_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id"));
CREATE TABLE "Campaign" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"type" "CampaignType" NOT NULL,"status" "CampaignStatus" NOT NULL DEFAULT 'DRAFT',"title" TEXT NOT NULL,"city" TEXT NOT NULL,"rewardPaisa" BIGINT NOT NULL,"cap" INTEGER NOT NULL,"successRule" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Campaign_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id"));
CREATE TABLE "Attribution" ("id" TEXT PRIMARY KEY,"code" TEXT NOT NULL UNIQUE,"campaignId" TEXT NOT NULL,"earnerId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE UNIQUE INDEX "Attribution_campaignId_earnerId_key" ON "Attribution"("campaignId","earnerId");
CREATE TABLE "Order" ("id" TEXT PRIMARY KEY,"campaignId" TEXT NOT NULL,"businessId" TEXT NOT NULL,"earnerId" TEXT NOT NULL,"attributionCode" TEXT NOT NULL,"customerName" TEXT NOT NULL,"customerPhoneHash" TEXT NOT NULL,"product" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'SUBMITTED',"idempotencyKey" TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id"),CONSTRAINT "Order_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id"),CONSTRAINT "Order_earnerId_fkey" FOREIGN KEY ("earnerId") REFERENCES "User"("id"));CREATE INDEX "Order_businessId_status_idx" ON "Order"("businessId","status");
CREATE TABLE "Reward" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL,"amountPaisa" BIGINT NOT NULL,"status" "RewardStatus" NOT NULL DEFAULT 'EARNED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Reward_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id"));
CREATE TABLE "LedgerEntry" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"kind" "LedgerKind" NOT NULL,"amountPaisa" BIGINT NOT NULL,"referenceType" TEXT NOT NULL,"referenceId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LedgerEntry_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id"));CREATE INDEX "LedgerEntry_userId_createdAt_idx" ON "LedgerEntry"("userId","createdAt");